function showWizard(){const info=healthInfo??{};$('wizard-connection').textContent=[info.version?`控制台版本 ${info.version}`:'控制台版本未返回',info.dataPath?`数据目录 ${info.dataPath}`:'数据目录未返回',info.stateDir?`状态目录 ${info.stateDir}`:'状态目录未返回'].join(' · ');$('wizard-writes').textContent=info.readOnly===true||snapshot?.writeEnabled===false?'当前为只读模式：可以浏览配置并生成预览，但保存需要以写入模式重新启动。':'当前允许保存：应用前会自动备份，并按资源逐项应用。';$('wizard').hidden=false;setWizardStep(1);}
