function formatBytes(bytes){const n=Number(bytes);if(!Number.isFinite(n)||n<0)return '未知';if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(2)} GB`;}
