async function loadBackups({manual=false}={}){if(!bridgeReadyFlag||backupLoading)return;backupLoading=true;backupTried=true;try{const params=isRemoteSnapshot(snapshot)&&snapshotWritable(snapshot)?deviceParams(selectedDevice):undefined;backups=await apiGet('backups',params);const keep=backups?.limits?.keep;if(Number.isFinite(keep))$('backup-keep').value=String(keep);renderBackups();if(manual)message(`已读取 ${backups?.backups?.length??0} 份备份。`);}catch(e){backups=null;renderBackups();if(handleDenied(e))return;$('backup-note').textContent=`备份接口暂不可用：${errorText(e)}`;if(manual)message($('backup-note').textContent,true);}finally{backupLoading=false;syncWriteControls();}}
function renderBackups(){const summary=$('backup-summary'),body=$('backup-body'),warningList=$('backup-warnings');if(!backups){summary.textContent='尚未读取备份信息。';body.replaceChildren();warningList.replaceChildren();warningList.hidden=true;return;}const warnings=backupWarnings(backups.warnings,5);warningList.replaceChildren(...warnings.map(warning=>el('li',`${warning.time?backupTime(warning.time)+' · ':''}${warning.code}：${warning.message||'无详情'}`)));warningList.hidden=!warnings.length;const list=backups.backups??[],stats=backups.stats??{},remote=isRemoteSnapshot(snapshot),canRestore=!remote;summary.textContent=`共 ${stats.count??list.length} 份备份 · 占用 ${formatBytes(stats.bytes??0)} · 保留上限 ${backups.limits?.keep??'未知'} 份${Number.isFinite(backups.limits?.maxBytes)?` · 容量上限 ${formatBytes(backups.limits.maxBytes)}`:''}`;$('backup-note').textContent=remote?(list.length?'远程 Agent 备份仅供查看；恢复仅在本机执行。':'远程 Agent 暂无备份。'):(list.length?'选择一份备份即可查看并恢复其中的资源；恢复前会先展示差异。':'暂无可用备份；应用修改前会自动创建备份。');const rows=list.map(item=>{const tr=el('tr');tr.append(el('td',item.id?.slice(0,8)??'未知'),el('td',backupTime(item.createdAt)),el('td',formatBytes(item.bytes??0)),el('td',String(item.files??'—')),el('td',item.sqlite??'未知'));const action=el('td');if(canRestore){const button=el('button','选择恢复','button quiet');button.disabled=busy||!localAdminWritable();button.addEventListener('click',()=>selectBackup(item));action.append(button);}else{action.append(el('span','仅本机可恢复','muted'));}tr.append(action);if(canRestore&&selectedBackup?.id===item.id)tr.className='selected';return tr;});if(rows.length)body.replaceChildren(...rows);else{const tr=el('tr'),cell=el('td','暂无备份。','empty-note');cell.colSpan=6;tr.append(cell);body.replaceChildren(tr);}}
function selectBackup(item){selectedBackup=item;restoreDiff=null;$('restore-panel').hidden=false;$('restore-diff-view').replaceChildren();$('restore-plan').disabled=true;renderRestoreResources();renderBackups();}
function renderRestoreResources(){const kind=$('restore-kind').value,select=$('restore-resource');select.replaceChildren();if(!snapshot)return;const options=kind==='provider'?(snapshot.models??[]).map(model=>[model.id,model.id]):(snapshot.resources??[]).filter(item=>item.resource.kind===kind).map(item=>[item.resource.id,resourceName(item.resource)]);for(const [value,label] of options)select.append(new Option(label,value));}
