let deviceSelectSignature='';
function renderDeviceSelect(){const select=$('device-select'),options=deviceOptions(devices);if(selectedDevice&&!options.some(option=>option.value===selectedDevice))options.push({value:selectedDevice,label:`设备 ${selectedDevice.slice(0,16)}…`,kind:'http',readOnly:true});const signature=JSON.stringify([selectedDevice,options.map(option=>[option.value,option.label])]);if(signature===deviceSelectSignature&&select.options.length===options.length)return;deviceSelectSignature=signature;select.replaceChildren(...options.map(option=>new Option(option.label,option.value)));select.value=options.some(option=>option.value===selectedDevice)?selectedDevice:'local';}
function renderDeviceTable(){const body=$('device-body');if(!devices){const tr=el('tr'),cell=el('td','尚未读取设备列表。','empty-note');cell.colSpan=6;tr.append(cell);body.replaceChildren(tr);return;}const rows=devices.map(device=>{const tr=el('tr');const kind=deviceKind(device),remote=kind!=='local';const badge=remote?healthBadge(deviceHealth.get(device.id)):{text:'本机',kind:'good'};const health=el('td'),badgeEl=el('span',badge.text,`health-badge ${badge.kind}`);health.append(badgeEl);const kindLabel=remote?deviceKindLabel(kind):`本机${device.readOnly?' · 只读':' · 可写'}`;const secret=remote?(device.hasSecret?'已保存':'缺失'):'—';const action=el('td');if(remote){const remove=el('button','删除','button quiet');remove.disabled=busy||!localAdminWritable();remove.addEventListener('click',()=>removeDevice(device));action.append(remove);}tr.append(el('td',device.name??device.id),el('td',kindLabel),el('td',device.baseUrl??'—'),health,el('td',secret),action);return tr;});if(rows.length)body.replaceChildren(...rows);else{const tr=el('tr'),cell=el('td','暂无远程设备；可在下方添加。','empty-note');cell.colSpan=6;tr.append(cell);body.replaceChildren(tr);}}
async function loadDevices({manual=false}={}){if(!bridgeReadyFlag||devicesLoading)return;devicesLoading=true;devicesTried=true;try{const result=await apiGet('devices');devices=Array.isArray(result?.devices)?result.devices:[];renderDeviceSelect();renderDeviceTable();if(manual)message(`已读取 ${devices.length} 台设备。`);void loadDeviceHealths();}catch(e){devices=null;renderDeviceSelect();renderDeviceTable();if(handleDenied(e))return;$('device-note').textContent=`设备接口暂不可用：${errorText(e)}`;if(manual)message($('device-note').textContent,true);}finally{devicesLoading=false;syncWriteControls();}}
async function loadDeviceHealths(){for(const device of devices??[]){if(deviceKind(device)==='local')continue;try{deviceHealth.set(device.id,await apiGet(`devices/${device.id}/health`));}catch(e){deviceHealth.set(device.id,{reachable:false,error:e?.message??'DEVICE_UNREACHABLE'});}}renderDeviceTable();}
async function switchDevice(){const value=$('device-select').value||'local';if(value===selectedDevice)return;if(inFlight){$('device-select').value=selectedDevice;message('正在同步配置，请稍后再切换设备。',true);return;}selectedDevice=value;drafts.clear();invalidatePlans();hideConflict();backups=null;backupTried=false;selectedBackup=null;restoreDiff=null;$('restore-panel').hidden=true;if($('review').open)$('review').close();message(value==='local'?'已切换到本机设备。':'正在读取远程设备…');await refresh({forceRender:true});}
function syncDeviceFormFields(){const kind=$('device-kind').value;const ssh=kind==='ssh',agent=kind==='agent';$('device-ssh-fields').hidden=!ssh;$('device-pairing-field').hidden=!agent;$('device-allow-write-field').hidden=!agent;$('device-key-field').hidden=agent;$('device-key').value='';$('device-pairing').value='';$('device-allow-write').checked=false;}
async function addDevice(event){event.preventDefault();if(busy||!bridgeReadyFlag||!localAdminWritable())return;const input={kind:$('device-kind').value,name:$('device-name').value,baseUrl:$('device-url').value,apiKey:$('device-key').value,pairingCode:$('device-pairing').value,host:$('device-ssh-host').value,port:$('device-ssh-port').value,user:$('device-ssh-user').value,keyPath:$('device-ssh-key').value,dataPath:$('device-ssh-data').value,allowWrite:$('device-allow-write').checked};$('device-key').value='';$('device-pairing').value='';$('device-allow-write').checked=false;const checked=validateDeviceInput(input);if(!checked.ok){message(deviceErrorText(checked.errors[0])||'请检查设备名称、地址与凭据。',true);return;}busy=true;syncWriteControls();try{const result=await apiPost('devices',checked.payload);$('device-name').value='';$('device-url').value='';await loadDevices();message(`已添加设备「${result?.device?.name??checked.payload.name}」${checked.payload.readOnly?'（只读）':'（允许远程写入）'}。`);}catch(e){if(!handleDenied(e))message(errorText(e),true);}finally{busy=false;renderDeviceTable();renderDrafts();syncWriteControls();}}
async function exportDiagnostics(){if(busy||!bridgeReadyFlag)return;busy=true;$('diagnostics-export').disabled=true;try{const data=await apiGet('diagnostics/export');const events=Array.isArray(data?.events)?data.events:[];const stamp=new Date().toISOString().slice(0,10).replaceAll('-','');await downloadFile('diagnostics/export',undefined,`model-console-diagnostics-${stamp}.json`);message(`已导出诊断事件 ${events.length} 条（不含令牌、密钥与配置值）。`);}catch(e){if(!handleDenied(e))message(`导出诊断失败：${errorText(e)}`,true);}finally{busy=false;$('diagnostics-export').disabled=false;syncWriteControls();}}
