function renderDrafts(){$('draft-count').textContent=String(drafts.size);const rows=[];for(const [key,d]of drafts){const item=el('div',undefined,'draft-item');item.append(el('strong',resourceName(d.resource)),el('small',labels[d.path]??d.path),el('small',`原值：${settingDraftText(d,d.baseValue)}`),el('small',`→ ${settingDraftText(d,d.value)}`,'to'));const remove=el('button','移除','button quiet');remove.disabled=busy||readOnlyView();remove.addEventListener('click',()=>{drafts.delete(key);invalidatePlans();renderDrafts();renderResources();renderModels();});item.append(remove);rows.push(item);}$('drafts').replaceChildren(...rows);if(!rows.length){const empty=el('div',undefined,'empty-drafts');empty.append(el('span','⇄'),document.createTextNode('还没有待应用的修改'),el('div','在卡片中选择模型即可暂存。'));$('drafts').append(empty);}$('prepare').disabled=busy||!drafts.size||readOnlyView();$('clear').disabled=busy||!drafts.size;syncWriteControls();}
function invalidatePlans(){plans=[];preparedDrafts=[];$('ack').checked=false;$('apply').disabled=true;}
function render(){if(!snapshot)return;refreshSummary();renderResources();renderModels();renderDrafts();}
async function refresh({manual=false,forceRender=false}={}){if(!bridgeReadyFlag||inFlight||busy||$('review').open)return;inFlight=true;$('refresh').disabled=true;try{const next=await apiGet('snapshot',deviceParams(selectedDevice));const changed=JSON.stringify(next.models)!==JSON.stringify(snapshot?.models)||JSON.stringify(next.resources)!==JSON.stringify(snapshot?.resources);snapshot=next;const resolved=next?.device?.id??'local';if(resolved!==selectedDevice)selectedDevice=resolved;if(!devicesTried)void loadDevices();if(!healthTried)void loadHealth();if(!backupTried)void loadBackups();if(!stateTried)void loadState();if(changed||forceRender||manual){const editing=['SELECT','INPUT'].includes(document.activeElement?.tagName)&&document.activeElement?.id!=='search';if(!editing||manual||forceRender)render();else refreshSummary();}else refreshSummary();if(manual)message('已读取最新配置；未保存的草稿保持不变。');}catch(e){if(handleDenied(e))return;if((e?.code??e?.message)==='CONCURRENT_CHANGE'){showConflict(null,null);message(errors.CONCURRENT_CHANGE,true);return;}$('mode').textContent='连接中断';$('mode').className='pill bad';message(errorText(e),true);}finally{inFlight=false;$('refresh').disabled=false;syncWriteControls();}}
function showReview(plansToShow,{restore=false}={}){plans=plansToShow;restore=restore||plans.some(plan=>plan?.mode==='restore');preparedDrafts=restore?[]:[...drafts.entries()];$('review-content').replaceChildren();for(const plan of plans){const item=el('div',undefined,'review-item');item.append(el('strong',resourceName(plan.resource)));for(const change of plan.changes??[]){if(restore){item.append(el('div',`${labels[change.path]??change.path}：${restoreDisplay(change.before??change.current)} → ${restoreDisplay(change.value)}`));}else{const draft=preparedDrafts.find(([,d])=>resourceKey(d.resource)===resourceKey(plan.resource)&&d.path===change.path)?.[1];if(change.secret){item.append(el('div',`${labels[change.path]??change.path}：${change.summary??'（已隐藏）'}`));}else{const reviewText=value=>change.path.startsWith('provider_settings.web')?webSearchValueText(change.path,value):(value||'空值 / 默认');item.append(el('div',`${labels[change.path]??change.path}：${reviewText(draft?.baseValue)} → ${reviewText(change.value)}`));}}}item.append(el('div',`影响范围：${plan.resource.kind==='provider'?'所有引用此模型的功能':plan.resource.kind==='plugin'?'使用此插件的全部账号':'当前账号 / 全局配置'}${restore?' · 恢复会覆盖该资源的完整对象':''}`,'muted'));$('review-content').append(item);}const warning=planWarning(plans.map(plan=>plan?.warning).find(text=>typeof text==='string'&&text.trim()),{restore});const warningEl=$('review-warning');warningEl.hidden=!warning;if(warning){warningEl.textContent=warning.text;warningEl.className=warning.kind==='danger'?'warning-text':'info-text';}$('ack').checked=false;$('apply').disabled=true;$('review').showModal();}
async function prepare(){if(busy||!drafts.size||!bridgeReadyFlag||readOnlyView())return;busy=true;renderDrafts();let latest=null,resource=null;try{latest=await apiGet('snapshot',deviceParams(selectedDevice));const planned=[];for(const group of groups(drafts)){resource=group.resource;const actual=currentRevision(latest,group.resource);if(!group.revision||actual!==group.revision)throw Error('CONCURRENT_CHANGE');const result=await apiPost('plans',{resource:group.resource,changes:group.changes,expectedRevision:group.revision,...postDeviceScope()});if(result.revision!==group.revision)throw Error('CONCURRENT_CHANGE');planned.push(result);}showReview(planned,{restore:false});}catch(e){if(handleDenied(e)){invalidatePlans();}else if((e?.code??e?.message)==='CONCURRENT_CHANGE'){showConflict(resource,latest);message(errors.CONCURRENT_CHANGE,true);invalidatePlans();}else{message(errorText(e),true);invalidatePlans();}}finally{busy=false;renderDrafts();syncWriteControls();}}
async function apply(){if(busy||!plans.length||!$('ack').checked||readOnlyView())return;busy=true;$('apply').disabled=true;$('close-review').disabled=true;$('cancel-review').disabled=true;let completed=0,hotLoad=null;const restoring=plans.some(plan=>plan?.mode==='restore');try{for(const plan of plans){const result=await apiPost('apply',{id:plan.id,...postDeviceScope()});hotLoad=result?.hotLoad??hotLoad;completed++;for(const [key,d]of preparedDrafts)if(resourceKey(d.resource)===resourceKey(plan.resource))drafts.delete(key);}const base=restoring?`已恢复并回读 ${completed} 个资源；恢复覆盖了所选资源的完整对象。`:`已保存并回读 ${completed} 个配置资源。未执行模型生成测试，也不以此认定实际调用成功。`;const hot=hotLoadMessage(hotLoad);message(hot?`${base} ${hot}`:base);}catch(e){const uncertain=e.details?.outcome==='possibly-written';if(!handleDenied(e))message(`已完成 ${completed} 个资源，后续保存停止。${uncertain?'当前资源可能已写入，请先核对配置与备份，不要直接重试。':errorText(e)}${e.details?.backupId?` 备份：${e.details.backupId}`:''}`,true);}finally{busy=false;$('close-review').disabled=false;$('cancel-review').disabled=false;$('review').close();invalidatePlans();renderDrafts();await refresh({forceRender:true});if(restoring||(isRemoteSnapshot(snapshot)&&snapshotWritable(snapshot)))await loadBackups();syncWriteControls();}}
function applyDocumentTitles(){const title=translate('pages.model-console.title','模型切换器');document.title=title;const heading=$('page-title');if(heading)heading.textContent=title;}
async function boot(){try{await bridgeReady();bridgeReadyFlag=true;}catch(error){message(errorText(error),true);$('mode').textContent='未连接';$('mode').className='pill bad';return;}applyDocumentTitles();onContext(()=>applyDocumentTitles());await refresh({forceRender:true});}
$('refresh').addEventListener('click',()=>refresh({manual:true}));$('search').addEventListener('input',event=>{search=event.target.value;if(snapshot){renderResources();renderModels();}});$('issues').addEventListener('change',event=>{onlyIssues=event.target.checked;if(snapshot){renderResources();renderModels();}});$('prepare').addEventListener('click',prepare);$('clear').addEventListener('click',()=>{drafts.clear();invalidatePlans();render();});$('ack').addEventListener('change',event=>{$('apply').disabled=!event.target.checked||busy;});$('apply').addEventListener('click',apply);for(const id of ['close-review','cancel-review'])$(id).addEventListener('click',()=>{if(!busy)$('review').close();});$('review').addEventListener('cancel',event=>{if(busy)event.preventDefault();});
